const $=s=>document.querySelector(s);const canvas=$('#world');
const lessons=WILLOW_LESSONS;
let saved;try{saved=JSON.parse(localStorage.getItem('uspeak-willow-v1'))}catch{}let done=Array.isArray(saved?.done)?saved.done.filter(n=>Number.isInteger(n)&&n>=0&&n<4):[];done=[...new Set(done)];let words=Array.isArray(saved?.words)?saved.words.filter(w=>Array.isArray(w)&&w.length===2&&w.every(s=>typeof s==='string')):[];let selected=lessons.findIndex((_,i)=>!done.includes(i));if(selected<0)selected=0;let muted=false,activeLesson=0,step=0,nearest=-1;const dialog=$('#dialog');
function persist(){try{localStorage.setItem('uspeak-willow-v1',JSON.stringify({done,words}))}catch{toast('このブラウザでは進捗を保存できません')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity=0,3500)}
function speak(s){if(muted)return;if(!('speechSynthesis'in window)){toast('このブラウザは音声再生に対応していません');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(s);u.lang='en-US';u.rate=.84;speechSynthesis.speak(u)}
function renderQuests(){$('#quests').innerHTML=lessons.map((q,i)=>`<button class="quest ${selected===i?'selected':''}" data-quest="${i}"><span class="num">${done.includes(i)?'✓':q.icon}</span><span><strong>${q.title}</strong><small>${q.name} · ${done.includes(i)?'COMPLETE':i===selected?'進行中 · +100 XP':'+100 XP'}</small></span><span class="arrow">›</span></button>`).join('');document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>{selected=+b.dataset.quest;const q=lessons[selected];player.position.set(q.x+2,0,q.z+3);renderQuests();toast(`${q.name} の近くに移動しました。E または「話す」で会話。`)});$('#count').textContent=`${done.length} / 4`;$('#progress').style.width=done.length*25+'%';$('#xp').textContent=done.length*100+rpg.store.state.xp;$('#level').textContent=1+Math.floor((done.length*100+rpg.store.state.xp)/100)}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();keys.clear()}
$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function conversation(i){activeLesson=i;step=0;showStep()}
function showStep(){const q=lessons[activeLesson],s=q.steps[step];openDialog(`<span class="npc-tag">${q.place.toUpperCase()} · ${step+1} / 3</span><h2>${q.name}</h2><div class="speech"><strong>${s[0]}</strong><p>${s[1]}</p><button id="listen">▷ お手本を聞く</button></div><p>英語で返してみよう</p>${s[2].map((a,j)=>`<button class="answer" data-answer="${j}">${String.fromCharCode(65+j)} &nbsp; ${a}</button>`).join('')}<p class="feedback" id="feedback" role="status"></p>`);$('#listen').onclick=()=>speak(s[0]);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{hooks.emit('answer',{q:`lesson:${activeLesson}:${step}`,c:+b.dataset.answer});if(+b.dataset.answer!==s[3]){$('#feedback').textContent='もう一度！相手の質問の意味を見てみよう。';b.disabled=true;return}document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);speak(s[4]);if(!words.some(w=>w[0]===s[4]))words.push([s[4],s[5]]);persist();$('#feedback').textContent=`✓ ${s[5]}`;let next=document.createElement('button');next.className='primary';next.textContent=step===2?'クエストを完了する ✦':'次の会話へ →';next.onclick=()=>{if(++step<3)showStep();else complete()};$('#dialog-content').appendChild(next)})}
function complete(){const fresh=!done.includes(activeLesson);if(fresh)done.push(activeLesson);persist();renderQuests();openDialog(`<span class="npc-tag">QUEST COMPLETE</span><h2>言葉が、つながった！</h2><p>${lessons[activeLesson].name} との会話をクリアしました。</p><div class="speech"><strong>${fresh?'+100 XP':'復習完了 ✓'}</strong><p>${done.length===4?'島のクエストをすべて達成！単語帳で12のフレーズを復習できます。':'覚えたフレーズは単語帳に保存されました。次の住人にも話しかけてみよう。'}</p></div><button class="primary" id="continue">冒険をつづける →</button>`);$('#continue').onclick=()=>{dialog.close();selected=lessons.findIndex((_,i)=>!done.includes(i));if(selected<0)selected=activeLesson;renderQuests()}}
$('#interact').onclick=()=>{if(rpg.inRoom)net.myRoom.placeHere();else if(net.ghostNearby())net.ghostSwing();else if(rpg.townNearby())net.townInteract();else if(rpg.rideNearby())net.rideInteract();else if(rpg.petNearby())net.petInteract();else if(rpg.arenaNearby())net.arenaInteract();else if(rpg.schoolNearby())net.schoolInteract();else if(rpg.errandNearby())net.errandInteract();else if(rpg.adventure.treasure.nearby())rpg.adventure.treasure.interact();else if(rpg.insidePark||rpg.parkNearby())rpg.openSanctuary();else if(nearest>=0)conversation(nearest);else if(rpg.nearby())rpg.encounter(rpg.nearby().id);else fishing.interactNear()};$('#phrase').onclick=()=>speak('Nice to meet you!');$('#sound').onclick=()=>{muted=!muted;$('#sound').textContent=muted?'♪̸':'♫';if(muted&&'speechSynthesis'in window)speechSynthesis.cancel();ambience.setMuted(muted);toast(muted?'音声をオフにしました':'音声をオンにしました')};
function help(){openDialog('<span class="npc-tag">HOW TO PLAY</span><h2>英語で、島を冒険しよう。</h2><p>「✈ RPGワールドマップ」から各地へ飛べます。草原で3種類の仲間を集めると、新しい地域が解放されます。WASD / 矢印キー、または画面左下のボタンで移動。Shift で走ります。V で一人称視点、H で景色に集中する画面に切り替えます。画面をドラッグすると視点が回ります。スクロールでズームできます。</p><p>各島に宝箱が3個あります。近づいて E キーまたは「調べる」で開封。鍵の手がかりはRPGメニューの「宝箱と鍵」で確認できます。</p><p>建物の「入口」に歩いて近づくと屋内へ移動します。入口の近くで E キー、または「入る」ボタンでも入れます。屋内では受付でサービスを利用でき、「出口」から同じ建物の前へ戻れます。島の小屋・お店・工場も同じで、歩いて入り、中のカウンターで E を押します。出るときは入口へ歩けば外に戻ります。</p><p>まちづくり島のマイルームでは、画面中央の十字（＋）でねらって「おく」（E）でブロックを置き、「ほる」（Q）で取り除きます。持つブロックは下のバーか数字キー 1〜9 で選びます。ブロックは床か、すでにあるブロックの面にだけ置けます。</p><p>住人に近づいて E キー、または「話す」ボタンで会話。左のクエストを押すと、その住人の近くへ移動できます。</p><p>正しい返答を選び、3つの会話を終えると100 XP。音声を聞いて、自分でも声に出してみましょう。進捗はこのブラウザに保存されます。</p><p>本作はMinecraft風の独立したWebゲームです。Minecraft・Roblox本体との接続機能はありません。</p>')}
$('#help').onclick=help;$('#explore').onclick=()=>{dialog.close();toast('気になる場所へ歩いてみよう。住人の近くで E を押して会話。')};$('#journal').onclick=()=>{openDialog('<span class="npc-tag">YOUR COLLECTION</span><h2>冒険の単語帳</h2><p>'+words.length+' フレーズを習得</p><div id="wordlist"></div>');if(!words.length)$('#wordlist').textContent='住人と会話すると、ここにフレーズが増えていきます。';words.forEach(w=>{let d=document.createElement('div');d.className='word';let text=document.createElement('div'),a=document.createElement('strong'),b=document.createElement('small'),bt=document.createElement('button');a.textContent=w[0];b.textContent=w[1];bt.textContent='▷ 聞く';bt.onclick=()=>speak(w[0]);text.append(a,b);d.append(text,bt);$('#wordlist').append(d)})};$('#mapbtn').onclick=()=>{if(rpg.insidePark){rpg.openMap();return}if(rpg.inRegion){rpg.openMap();return}if(park.state.inPark){toast('右上の地図と左の乗り物メニューで島を探索できます。');return}openDialog('<span class="npc-tag">ISLAND GUIDE</span><h2>次は、どこへ行こう？</h2><p>場所を選んで、住人の近くに移動できます。</p>'+lessons.map((q,i)=>`<button class="answer" data-travel="${i}">${q.icon} &nbsp; ${q.place} <small> · ${q.name}</small></button>`).join(''));document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{selected=+b.dataset.travel;let q=lessons[selected];player.position.set(q.x+2,0,q.z+3);dialog.close();renderQuests()})};$('#home').onclick=()=>{if(rpg.insidePark){rpg.leaveSanctuary();return}if(rpg.inRegion){rpg.openMap();return}if(park.state.inPark){park.booking();return}player.position.set(3,0,8);toast('はじまりの広場に戻りました')};
